package com.example.starter.pump.repo;

import com.example.starter.pump.web.dto.ReplayResult;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.List;

/**
 * 泵站启停任务、启停序列与分区序列锁仓储。
 *
 * <p>并发约束由数据库保证：
 * <ul>
 *   <li>{@code uk_station_time(station_code, task_time)}：同一泵站同时刻唯一任务；</li>
 *   <li>{@code zone_sequence_lock} 主键为分区：同一分区同时刻仅一套序列。</li>
 * </ul>
 */
@Repository
public class PumpTaskRepository {

    private final JdbcTemplate jdbc;

    public PumpTaskRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 尝试为分区持有活动序列锁。
     *
     * @return true 获取成功；false 该分区已有另一套活动序列
     */
    public boolean tryAcquireZoneLock(String zoneCode, Long pumpdownId, Long sequenceId,
                                      LocalDateTime now) {
        try {
            jdbc.update(
                    """
                    INSERT INTO zone_sequence_lock (zone_code, pumpdown_id, sequence_id, acquired_at)
                    VALUES (?, ?, ?, ?)
                    """,
                    zoneCode, pumpdownId, sequenceId, now);
            return true;
        } catch (DuplicateKeyException e) {
            return false;
        }
    }

    /** 锁是否由指定预降事件持有。 */
    public boolean lockHeldBy(String zoneCode, Long pumpdownId) {
        Integer cnt = jdbc.queryForObject(
                "SELECT COUNT(1) FROM zone_sequence_lock WHERE zone_code = ? AND pumpdown_id = ?",
                Integer.class, zoneCode, pumpdownId);
        return cnt != null && cnt > 0;
    }

    /** 释放分区序列锁。 */
    public void releaseZoneLock(String zoneCode, Long pumpdownId) {
        jdbc.update(
                "DELETE FROM zone_sequence_lock WHERE zone_code = ? AND pumpdown_id = ?",
