@SpringBootTest
@ActiveProfiles("test")
public abstract class AbstractIntegrationTest {

    private static final List<String> BUSINESS_TABLES = List.of(
            "gate_opening_log",
            "pump_task",
            "pump_sequence",
            "level_reading",
            "late_reading_event",
            "miss_contact_order",
            "review_archive",
            "pumpdown_event",
